glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
#extension GL_OES_standard_derivatives : enable
#ifdef GL_FRAGMENT_PRECISION_HIGH
  precision highp float;
#else
  precision mediump float;
#endif
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
in vec4 v_color;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform sampler2D digitAtlas;
uniform UBO_FS {
  vec2 gridSize;
  vec2 digitInfo;
  vec2 cellPad;
  vec2 lineWidth;
  vec4 gridLineColor;
};
void main () {
  #if USE_TEXTURE
  vec2 texelSize = 1.0 / gridSize;
  vec2 cellIdx = floor(v_uv0 * gridSize);
  vec2 cellCenter = (cellIdx + 0.5) * texelSize;
  float digitIndex = floor(texture2D(texture, cellCenter).r * 255.0 + 0.5);
  if (digitIndex < 0.5) {
    discard;
  }
  vec2 cellLocal = fract(v_uv0 * gridSize);
  #ifdef GL_OES_standard_derivatives
    vec2 fw = fwidth(v_uv0 * gridSize);
  #else
    vec2 fw = vec2(0.001);
  #endif
  vec2 lw = max(lineWidth, fw);
  float leftEdge  = 1.0 - smoothstep(lw.x - fw.x, lw.x + fw.x, cellLocal.x);
  float rightEdge = smoothstep(1.0 - lw.x - fw.x, 1.0 - lw.x + fw.x, cellLocal.x);
  float topEdge   = 1.0 - smoothstep(lw.y - fw.y, lw.y + fw.y, cellLocal.y);
  float botEdge   = smoothstep(1.0 - lw.y - fw.y, 1.0 - lw.y + fw.y, cellLocal.y);
  float isLine = max(max(leftEdge, rightEdge), max(topEdge, botEdge));
  float padX = cellPad.x;
  float padY = cellPad.y;
  bool inDigitArea = cellLocal.x >= padX && cellLocal.x <= 1.0 - padX
                  && cellLocal.y >= padY && cellLocal.y <= 1.0 - padY;
  vec4 digitColor = vec4(0.0);
  if (inDigitArea) {
    float localX = (cellLocal.x - padX) / (1.0 - 2.0 * padX);
    float localY = (cellLocal.y - padY) / (1.0 - 2.0 * padY);
    float atlasCols = digitInfo.x;
    float atlasRows = digitInfo.y;
    float idx = digitIndex - 1.0;
    float col = mod(idx, atlasCols);
    float row = floor(idx / atlasCols);
    float digitU = (col + localX) / atlasCols;
    float digitV = (row + localY) / atlasRows;
    digitColor = texture2D(digitAtlas, vec2(digitU, digitV)) * v_color;
  }
  if (digitColor.a > 0.01) {
    gl_FragColor = digitColor;
  } else if (isLine > 0.01) {
    vec4 lineColor = gridLineColor;
    lineColor.a *= isLine * v_color.a;
    gl_FragColor = lineColor;
  } else {
    discard;
  }
  #else
  gl_FragColor = v_color;
  #endif
}

